"""Explicit archive restoration through real HTTP/storage; faults drop ACK after a real write."""
import asyncio,json,os
from datetime import datetime,timezone,timedelta
from pathlib import Path
from playwright.async_api import async_playwright,expect
ROOT=Path(__file__).resolve().parents[4]
async def main():
 env={**os.environ,'YOURWIKI_BROWSER_PORT':'39088','YOURWIKI_BROWSER_CONTROL':'1'}
 server=await asyncio.create_subprocess_exec('node','apps/server/test/support/pdf-browser-server.ts',cwd=ROOT,env=env,stdin=asyncio.subprocess.PIPE,stdout=asyncio.subprocess.PIPE,stderr=asyncio.subprocess.PIPE)
 async def command(action):
  server.stdin.write((json.dumps({'action':action})+'\n').encode());await server.stdin.drain();result=json.loads(await asyncio.wait_for(server.stdout.readline(),30));assert result['ok'],result;return result
 try:
  assert b'Synthetic PDF' in await asyncio.wait_for(server.stdout.readline(),20);docs=await command('history-fixtures')
  async with async_playwright() as p:
   browser=await p.chromium.launch(executable_path=os.environ['PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH'],headless=True,args=['--no-sandbox']);context=await browser.new_context(locale='ru-RU',viewport={'width':393,'height':852});page=await context.new_page();page.set_default_timeout(5000);errors=[];writes=[]
   page.on('pageerror',lambda error:errors.append(str(error)));page.on('request',lambda req:writes.append(req.url) if req.method=='POST' and ('/restore' in req.url or '/history-restores/' in req.url) else None)
   await page.goto('http://127.0.0.1:39088/');await page.locator('input[name=username]').fill('qa');await page.locator('input[name=password]').fill('yourwiki-qa');await page.get_by_role('button',name='Войти',exact=True).click();await page.get_by_role('link',name='MD Live notes').click();await page.frame_locator('iframe.document-frame').get_by_role('heading',name='Current live notes',exact=True).wait_for();await page.get_by_role('button',name='История версий',exact=True).click();rows=page.locator('.history-list>li');await expect(rows).to_have_count(50);await rows.first.get_by_role('button',name='Восстановить версию',exact=True).click();await page.get_by_role('button',name='Подтвердить восстановление',exact=True).wait_for();assert not writes,writes
   await page.get_by_role('button',name='Подтвердить восстановление',exact=True).click();await page.get_by_text('Версия восстановлена в Yourwiki. Синхронизация с внешним сервисом ещё не подтверждена.',exact=True).wait_for();assert len(writes)==2,writes;await command('history-work');await page.frame_locator('.document-editor iframe.document-frame').get_by_role('heading',name='Archived note 54',exact=True).wait_for();# A confirmation is stale after another writer; it must send no mutation.
   writes.clear();await rows.first.get_by_role('button',name='Восстановить версию',exact=True).click();await page.get_by_role('button',name='Подтвердить восстановление',exact=True).wait_for();await command('notes');await page.get_by_role('button',name='Подтвердить восстановление',exact=True).click();await page.get_by_text('Оригинал изменился. Текущие правки не перезаписаны. Для новой попытки проверьте актуальную версию и подтвердите замену ещё раз.',exact=True).wait_for();assert not writes,writes
   # Drop only the successful commit response: the real write must be read back, not retried.
   async def drop_commit(route):
    response=await route.fetch();assert response.status==200;await route.abort('failed')
   await page.route('**/history-restores/*/commit',drop_commit);await page.get_by_role('button',name='Подтвердить восстановление',exact=True).click();await page.get_by_text('Версия восстановлена в Yourwiki. Синхронизация с внешним сервисом ещё не подтверждена.',exact=True).wait_for();assert len(writes)==2,writes;await page.unroute('**/history-restores/*/commit',drop_commit);await command('history-work')
   # Drop staging ACK; closing and reopening history recovers the opaque journal with GET only.
   writes.clear();await rows.first.get_by_role('button',name='Восстановить версию',exact=True).click();await page.get_by_role('button',name='Подтвердить восстановление',exact=True).wait_for()
   async def drop_stage(route):
    if route.request.method=='POST':
     response=await route.fetch();assert response.status==202;await route.abort('failed')
    else:await route.continue_()
   await page.route('**/history/*/restore',drop_stage);await page.get_by_role('button',name='Подтвердить восстановление',exact=True).click();await page.get_by_role('button',name='Продолжить восстановление',exact=True).wait_for();assert len(writes)==1,writes;await expect(page.locator('.document-editor')).to_have_attribute('inert','');await page.get_by_role('button',name='Закрыть историю',exact=True).click();await page.get_by_role('button',name='Показать восстановление',exact=True).click();await page.get_by_role('button',name='Продолжить восстановление',exact=True).wait_for();assert len(writes)==1,writes;await page.unroute('**/history/*/restore',drop_stage);await page.get_by_role('button',name='Отменить восстановление',exact=True).click();await page.get_by_text('Восстановление отменено. Текущий файл не заменён.',exact=True).wait_for();assert len(writes)==2,writes;await expect(page.locator('.document-editor')).not_to_have_attribute('inert','')
   # Current PDF edits survive both inspection and refused restore without a write or exit prompt.
   await page.get_by_role('link',name='Документы',exact=True).click();await page.get_by_role('link',name='PDF PDF forms').click();field=page.locator('.pdf-container input').first;await field.wait_for();await page.clock.install();await page.clock.pause_at(datetime.now(timezone.utc)+timedelta(seconds=1));await page.evaluate('window.restoreRetainedField=document.querySelector(".pdf-container input")');await field.fill('Keep my current PDF changes');await page.get_by_role('button',name='История версий',exact=True).click();await expect(rows).to_have_count(1);writes.clear();await rows.first.get_by_role('button',name='Восстановить версию',exact=True).click();await page.get_by_role('button',name='Подтвердить восстановление',exact=True).click();await page.get_by_text('В редакторе есть несохранённые правки. Сначала сохраните или скопируйте их; восстановление не начато.',exact=True).wait_for();assert not writes,writes;assert await page.evaluate('window.restoreRetainedField===document.querySelector(".pdf-container input")');assert await field.input_value()=='Keep my current PDF changes';assert not errors,errors
   assert await page.evaluate('document.documentElement.scrollWidth===innerWidth');artifact=ROOT/'output/playwright/history-restore-mobile.png';artifact.parent.mkdir(parents=True,exist_ok=True);await page.screenshot(path=str(artifact))
   # Another clean reader can restore the archived PDF layer; the dirty reader must retain its own buffer.
   clean_context=await browser.new_context(locale='ru-RU',storage_state=await context.storage_state());clean=await clean_context.new_page();clean.set_default_timeout(8000);clean.on('pageerror',lambda error:errors.append(str(error)));await clean.goto('http://127.0.0.1:39088/documents/'+docs['pdf']);await clean.locator('.pdf-container input').first.wait_for();await clean.get_by_role('button',name='История версий',exact=True).click();await clean.locator('.history-list>li').first.get_by_role('button',name='Восстановить версию',exact=True).click();await clean.get_by_role('button',name='Подтвердить восстановление',exact=True).click();await clean.get_by_text('Версия восстановлена в Yourwiki. Синхронизация с внешним сервисом ещё не подтверждена.',exact=True).wait_for();layer=await (await clean.request.get('http://127.0.0.1:39088/api/documents/'+docs['pdf']+'/pdf')).json();assert layer['layerRevision']==2,layer;await clean.locator('.pdf-container input').first.wait_for();assert await page.evaluate('window.restoreRetainedField===document.querySelector(".pdf-container input")');assert await field.input_value()=='Keep my current PDF changes';assert not errors,errors;await clean_context.close()
   print(json.dumps({'historyRestore'  :'passed','explicitConfirmation':True,'staleConfirmationNoWrite':True,'lostCommitAckNoReplay':True,'stagedJournalRecovery':True,'explicitDiscard':True,'dirtyPdfRetained':True,'cleanPdfLayerRestored':True,'writesForDirtyPdf':len(writes),'errors':errors}));await browser.close()
 finally:
  if server.returncode is None:server.terminate()
  try:await asyncio.wait_for(server.wait(),15)
  except asyncio.TimeoutError:server.kill();await server.wait()
asyncio.run(main())
